          mapY: fixture.y,
          mapWidth: fixture.width,
          mapHeight: fixture.height,
          mapRotation: fixture.rotation,
          targetGroupKey: fixture.targetGroupKey,
          targetSpatialGroupId: fixture.targetSpatialGroupId,
