      originalName: String(file.name || "").slice(0, 250),
      relativePath,
      extension,
      mimeType: String(file.type || "").slice(0, 120),
      sizeBytes: Number(file.size) || 0,
      modifiedAt: new Date(file.lastModified || Date.now()).toISOString(),
